with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY))) as HUB_FINANCIAL_TRANSACTION_HK
        , PAY_TO_INSURED as PAY_TO_INSURED_INDICATOR
        , PAY_TO_HOSPITAL as PAY_TO_HOSPITAL_INDICATOR
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(TPA_TRANS_KEY),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAY_TO_INSURED_INDICATOR end) as PAY_TO_INSURED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAY_TO_HOSPITAL_INDICATOR end) as PAY_TO_HOSPITAL_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when PAY_TO_INSURED_INDICATOR is not null or PAY_TO_HOSPITAL_INDICATOR is not null
                     then md5(upper(coalesce(cast(PAY_TO_INSURED_INDICATOR as varchar), '') || '|' || coalesce(cast(PAY_TO_HOSPITAL_INDICATOR as varchar), '')))
                end as SAT_FINTXN_CLAIM_PAYMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_CLAIM_PAYMENT_HASHDIFF is not null
